"""Seating charts: students in rows by last name."""

def _sort_key(student):
    name = student.last_name, student.first_name
    return tuple(part.lower() for part in name)

def _sorted_names(students):
    ordered = sorted(students, key=_sort_key)
    return [item.display_name for item in ordered]

def _chunks(names, seats):
    return [names[start:start + seats]
            for start in range(0, len(names), seats)]

def _line(number, row):
    return f"Row {number}: " + " | ".join(row)

# ---
def seat_rows(students, seats):
    """One text line per row, sorted by last name."""
    if seats <= 0 or not students:
        raise ValueError("need students and seats")
    names = _sorted_names(students)
    rows = _chunks(names, seats)
    return [_line(*pair) for pair in enumerate(rows, 1)]

