import unittest

from rosterkit.models import Student
from rosterkit.seating import seat_rows

def make(last, first):
    return Student("1", last, first, "A")

ROSTER = [
    make("Halloway", "Juno"),
    make("Zane", "Omar"),
    make("Dunmere", "Piet")
]
EXPECTED = [
    "Row 1: Dunmere, Piet | Halloway, Juno",
    "Row 2: Zane, Omar"
]

class SeatRowsTests(unittest.TestCase):
    def test_sorts_and_splits_rows(self):
        result = seat_rows(ROSTER, 2)
        self.assertEqual(result, EXPECTED)

    def test_bad_seat_counts(self):
        roster = [make("Zane", "Omar")]
        for seats in (0, -1):
            with self.assertRaises(ValueError):
                seat_rows(roster, seats)

    def test_no_students(self):
        with self.assertRaises(ValueError):
            seat_rows([], 3)
